mapper.select:
select br.id, br.reporter_id as reporterId, u.username as reporterName, br.blog_id, b.title as blog_title, br.report_time, br.report_reason, br.status, br.reviewer_id, a.username as reviewer_name, br.review_time, br.review_result, br.review_reason, br.reported_user_id as reportedUserId from blog_report br left join user u on br.reporter_id = u.id left join blog b on br.blog_id = b.id left join user a on br.reviewer_id = a.id
and br.status = #{status}
and br.reporter_id = #{reporterId}
and br.blog_id = #{blogId}
and br.reviewer_id = #{reviewerId}
and u.username like concat('%', #{reporterName}, '%')
order by br.report_time desc
